SELECT budget_bucket, location, legal_budget FROM (SELECT CASE WHEN budget >= 3571000 THEN 'high' WHEN budget >= 1282000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, SUM(CASE WHEN dept_name = 'Legal' THEN budget ELSE 0 END) AS legal_budget FROM departments WHERE budget < 2021000 GROUP BY CASE WHEN budget >= 3571000 THEN 'high' WHEN budget >= 1282000 THEN 'mid' ELSE 'low' END, location) AS agg WHERE legal_budget < 65 ORDER BY location, budget_bucket LIMIT 3
